1. package resource
2. 
3. import (
4. 	"fmt"
5. 	"log"
6. 	"reflect"
7. 	"strings"
8. 	"testing"
9. 
10. 	"github.com/davecgh/go-spew/spew"
11. 	tfjson "github.com/hashicorp/terraform-json"
12. 	"github.com/hashicorp/terraform-plugin-sdk/acctest"
13. 	"github.com/hashicorp/terraform-plugin-sdk/terraform"
14. 	tftest "github.com/hashicorp/terraform-plugin-test"
15. )
16. 
17. func getState(t *testing.T, wd *tftest.WorkingDir) *terraform.State {
18. 	jsonState := wd.RequireState(t)
19. 	state, err := shimStateFromJson(jsonState)
20. 	if err != nil {
21. 		t.Fatal(err)
22. 	}
23. 	return state
24. }
25. 
26. func RunNewTest(t *testing.T, c TestCase, providers map[string]terraform.ResourceProvider) {
27. 	spewConf := spew.NewDefaultConfig()
28. 	spewConf.SortKeys = true
29. 	wd := acctest.TestHelper.RequireNewWorkingDir(t)
30. 
31. 	defer func() {
32. 		wd.RequireDestroy(t)
33. 
34. 		if c.CheckDestroy != nil {
35. 			statePostDestroy := getState(t, wd)
36. 
37. 			if err := c.CheckDestroy(statePostDestroy); err != nil {
38. 				t.Fatal(err)
39. 			}
40. 		}
41. 		wd.Close()
42. 	}()
43. 
44. 	providerCfg := testProviderConfig(c)
45. 
46. 	wd.RequireSetConfig(t, providerCfg)
47. 	wd.RequireInit(t)
48. 
49. 	// use this to track last step succesfully applied
50. 	// acts as default for import tests
51. 	var appliedCfg string
52. 
53. 	for i, step := range c.Steps {
54. 
55. 		if step.PreConfig != nil {
56. 			step.PreConfig()
57. 		}
58. 
59. 		if step.SkipFunc != nil {
60. 			skip, err := step.SkipFunc()
61. 			if err != nil {
62. 				t.Fatal(err)
63. 			}
64. 			if skip {
65. 				log.Printf("[WARN] Skipping step %d", i)
66. 				continue
67. 			}
68. 		}
69. 
70. 		if step.ImportState {
71. 			step.providers = providers
72. 			err := testStepNewImportState(t, c, wd, step, appliedCfg)
73. 			if err != nil {
74. 				t.Fatal(err)
75. 			}
76. 			continue
77. 		}
78. 
79. 		if step.Config != "" {
80. 			err := testStepNewConfig(t, c, wd, step)
81. 			if step.ExpectError != nil {
82. 				if err == nil {
83. 					t.Fatal("Expected an error but got none")
84. 				}
85. 				if !step.ExpectError.MatchString(err.Error()) {
86. 					t.Fatalf("Expected an error with pattern, no match on: %s", err)
87. 				}
88. 			} else {
89. 				if err != nil {
90. 					t.Fatal(err)
91. 				}
92. 			}
93. 			appliedCfg = step.Config
94. 			continue
95. 		}
96. 
97. 		t.Fatal("Unsupported test mode")
98. 	}
99. }
100. 
101. func planIsEmpty(plan *tfjson.Plan) bool {
102. 	for _, rc := range plan.ResourceChanges {
103. 		if rc.Mode == tfjson.DataResourceMode {
104. 			// Skip data sources as the current implementation ignores
105. 			// existing state and they are all re-read every time
106. 			continue
107. 		}
108. 
109. 		for _, a := range rc.Change.Actions {
110. 			if a != tfjson.ActionNoop {
111. 				return false
112. 			}
113. 		}
114. 	}
115. 	return true
116. }
117. func testIDRefresh(c TestCase, t *testing.T, wd *tftest.WorkingDir, step TestStep, r *terraform.ResourceState) error {
118. 	spewConf := spew.NewDefaultConfig()
119. 	spewConf.SortKeys = true
120. 
121. 	// Build the state. The state is just the resource with an ID. There
122. 	// are no attributes. We only set what is needed to perform a refresh.
123. 	state := terraform.NewState()
124. 	state.RootModule().Resources = make(map[string]*terraform.ResourceState)
125. 	state.RootModule().Resources[c.IDRefreshName] = &terraform.ResourceState{}
126. 
127. 	// Temporarily set the config to a minimal provider config for the refresh
128. 	// test. After the refresh we can reset it.
129. 	cfg := testProviderConfig(c)
130. 	wd.RequireSetConfig(t, cfg)
131. 	defer wd.RequireSetConfig(t, step.Config)
132. 
133. 	// Refresh!
134. 	wd.RequireRefresh(t)
135. 	state = getState(t, wd)
136. 
137. 	// Verify attribute equivalence.
138. 	actualR := state.RootModule().Resources[c.IDRefreshName]
139. 	if actualR == nil {
140. 		return fmt.Errorf("Resource gone!")
141. 	}
142. 	if actualR.Primary == nil {
143. 		return fmt.Errorf("Resource has no primary instance")
144. 	}
145. 	actual := actualR.Primary.Attributes
146. 	expected := r.Primary.Attributes
147. 	// Remove fields we're ignoring
148. 	for _, v := range c.IDRefreshIgnore {
149. 		for k := range actual {
150. 			if strings.HasPrefix(k, v) {
151. 				delete(actual, k)
152. 			}
153. 		}
154. 		for k := range expected {
155. 			if strings.HasPrefix(k, v) {
156. 				delete(expected, k)
157. 			}
158. 		}
159. 	}
160. 
161. 	if !reflect.DeepEqual(actual, expected) {
162. 		// Determine only the different attributes
163. 		for k, v := range expected {
164. 			if av, ok := actual[k]; ok && v == av {
165. 				delete(expected, k)
166. 				delete(actual, k)
167. 			}
168. 		}
169. 
170. 		spewConf := spew.NewDefaultConfig()
171. 		spewConf.SortKeys = true
